def pytest_collection_modifyitems(config, items):
    for item in items:
        nodeid = item.nodeid.replace("\\", "/")
        reason = QUARANTINE_STALE.get(nodeid)
        if reason:
            item.add_marker(pytest.mark.skip(reason=f"QUARANTINE stale (pre-P0): {reason}"))
